SELECT * FROM (SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'D:'||dispatch_id||':requested' event_id,'Dispatch Requested' activity,requested_at timestamp,dispatch_id source_key FROM dispatch_order WHERE requested_at IS NOT NULL AND (1=1)) e JOIN dispatch_order s ON s.dispatch_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'D:'||dispatch_id||':approved' event_id,'Dispatch Approved' activity,approved_at timestamp,dispatch_id source_key FROM dispatch_order WHERE approved_at IS NOT NULL AND (1=1)) e JOIN dispatch_order s ON s.dispatch_id=e.source_key WHERE s.dispatch_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
